"""Repeat the model's form steps for the next position (no model call per position).

A bid form often asks for one position after another with the same controls. After the model has filled one
position with `steps`, every value it typed or chose is traced back to the field of that position's line in our bid
table (material, quantity, prices, lead time, product filters). If every value is explained, the same steps are run
for the next position the page shows, with that position's values. A value that fits several fields (e.g. two
amounts of 0,00) is used only while those fields agree for the next position; anything unexplained, an unknown next
position or any error hands the form back to the model. The review check before signing compares the result.
"""
import re
from decimal import Decimal

Slot = tuple[int, int | None]          # (step index, field index in a fill_fields step or None)

FORMAT_ORDER = ("raw", "int", "de", "de_plain", "dot2")
MONEY = ("unit_price", "base_unit_price", "surcharge_per_unit", "packaging_per_unit", "rebate_total")


def _de(value: Decimal, grouped: bool = True) -> str:
    text = f"{value:,.2f}".replace(",", "_").replace(".", ",").replace("_", ".")
    return text if grouped else text.replace(".", "")


def render(fmt: str, value) -> str:
    if fmt == "int":
        return str(int(Decimal(str(value))))
    if fmt in ("de", "de_plain", "dot2"):
        number = Decimal(str(value))
        return _de(number) if fmt == "de" else _de(number, grouped=False) if fmt == "de_plain" else f"{number:.2f}"
    return str(value)


def representations(row: dict, filters: dict | None) -> dict[str, list[tuple[str, str]]]:
    """field -> [(format, text)] of one line of the bid table."""
    reps: dict[str, list[tuple[str, str]]] = {}
    if row.get("material_number"):
        reps["material_number"] = [("raw", str(row["material_number"]))]
    for key in ("quantity", "lead_time_weeks"):
        if row.get(key) is not None:
            reps[key] = [("int", render("int", row[key]))]
    for key in MONEY:
        if row.get(key) is not None:
            reps[key] = [(fmt, render(fmt, row[key])) for fmt in ("de", "de_plain", "dot2")]
    for key, value in (filters or {}).items():
        if value not in (None, ""):
            reps[f"filter:{key}"] = [("raw", str(value))]
    return reps


def _norm(text) -> str:
    return " ".join(str(text).split()).casefold()


def slots(steps: list[dict]) -> list[tuple[Slot, str, str]]:
    """Every value the steps enter: (slot, value, how) with how = select | text | field."""
    found = []
    for i, step in enumerate(steps):
        action = step.get("action")
        if action == "select" and step.get("option") not in (None, ""):
            found.append(((i, None), str(step["option"]), "select"))
        elif action == "type" and step.get("text") not in (None, ""):
            found.append(((i, None), str(step["text"]), "text"))
        elif action == "fill_fields":
            for j, field in enumerate(step.get("fields") or []):
                value = next((field.get(k) for k in ("value", "text", "option") if field.get(k) is not None), None)
                if value is not None:
                    found.append(((i, j), str(value), "field"))
    return found


def readbacks(steps: list[dict], result: str) -> dict[Slot, str]:
    """The option a select actually took (its value), from the steps' result text."""
    lines = {int(m.group(1)) - 1: m.group(2) for m in re.finditer(r"^(\d+)\. \w+: (.*)$", result, re.M)}
    out: dict[Slot, str] = {}
    for i, step in enumerate(steps):
        line = lines.get(i, "")
        if step.get("action") == "select":
            m = re.search(r"selected '([^']*)'", line)
            if m:
                out[(i, None)] = m.group(1)
        elif step.get("action") == "fill_fields":
            for j, field in enumerate(step.get("fields") or []):
                ref = re.sub(r"[^\w]", "", str(field.get("ref", "")))
                m = re.search(rf"(?<!\w){re.escape(ref)}: selected '([^']*)'", line) if ref else None
                if m:
                    out[(i, j)] = m.group(1)
    return out


def learn(steps: list[dict], result: str | dict, row: dict, filters: dict | None) -> dict[Slot, set[tuple[str, str]]] | None:
    """slot -> candidate (field, format) pairs, or None when a value is not explained by this line of the table.
    `result` is the steps' result text or their readbacks."""
    reps = representations(row, filters)
    back = result if isinstance(result, dict) else readbacks(steps, result)
    template: dict[Slot, set[tuple[str, str]]] = {}
    for slot, value, how in slots(steps):
        seen = {_norm(value)} | ({_norm(back[slot])} if slot in back else set())
        candidates = {(field, fmt) for field, forms in reps.items() for fmt, text in forms if _norm(text) in seen}
        if not candidates:
            if how != "select" and _norm(value) in ("true", "false", "on", "off", "yes", "no", "ja", "nein"):
                continue                                    # a checkbox: the same for every position
            return None
        template[slot] = candidates
    fields = {field for candidates in template.values() for field, _ in candidates}
    if "material_number" not in fields or "quantity" not in fields:
        return None                                        # not the form of one position
    return template


def merge(old: dict | None, new: dict | None) -> dict | None:
    """Two lines filled with the same steps: keep the explanations both agree on. A different form (other slots) or a
    contradiction keeps the newest template."""
    if old is None or new is None or old.keys() != new.keys():
        return new if new is not None else old
    merged = {slot: old[slot] & new[slot] for slot in old}
    return merged if all(merged.values()) else new


def fill(steps: list[dict], template: dict, row: dict, filters: dict | None) -> list[dict] | None:
    """The same steps with the values of another line, or None if a value is unknown or ambiguous for it."""
    values = {}
    for field, forms in representations(row, filters).items():
        for fmt, text in forms:
            values[(field, fmt)] = text
    out = [dict(s, fields=[dict(f) for f in s["fields"]]) if isinstance(s.get("fields"), list) else dict(s) for s in steps]
    for (i, j), candidates in template.items():
        chosen: dict[str, str] = {}             # one format per field: below 1000, 680,37 is grouped and plain alike
        for field, fmt in sorted(candidates, key=lambda c: FORMAT_ORDER.index(c[1])):
            chosen.setdefault(field, fmt)
        texts = {values.get((field, fmt)) for field, fmt in chosen.items()}
        if None in texts or len(texts) != 1:
            return None
        text = texts.pop()
        if j is None:
            out[i]["option" if out[i].get("action") == "select" else "text"] = text
        else:
            field = out[i]["fields"][j]
            for key in ("text", "option"):
                field.pop(key, None)
            field["value"] = text
    return out


def shown_position(page: str, ids: list[str]) -> str | None:
    """The one position id among `ids` that the page names (none or several: unknown)."""
    hits = [pid for pid in ids if re.search(rf"(?<![\w.,]){re.escape(pid)}(?![\w]|[.,]\d)", page)]
    return hits[0] if len(hits) == 1 else None
"""Feature switches, read from the environment once at start (1/true/on or 0/false/off).

Defaults are the behaviour validated in sandbox test runs; a test run can switch a feature on or off with
dev/eval/make_variant.py, without changing agent/. Code reads them as `flags.NAME` at call time, so tests can
monkeypatch them. Status and validation of every switch: docs/13-optimization-roadmap.md.
"""
import os


def _on(name: str, default: bool) -> bool:
    value = os.environ.get(name)
    return default if value is None else value.strip().lower() in ("1", "true", "yes", "on")


# shipped and validated (switches exist for a quick rollback)
BACKGROUND_EXTRACTION = _on("RFQ_BACKGROUND_EXTRACTION", True)  # ERP and mail missions navigate on while extracting
REVIEW_PREFETCH = _on("RFQ_REVIEW_PREFETCH", True)              # read the review page while the TAN arrives
STEPS_TOOL = _on("RFQ_STEPS_TOOL", True)                        # submission: several form actions in one step
START_OVERLAP = _on("RFQ_START_OVERLAP", True)                  # websites load while the brief is read
FORM_REPLAY = _on("RFQ_FORM_REPLAY", True)                      # submission: the next position with the same steps
AUTO_VISION = _on("RFQ_AUTO_VISION", True)                      # pictures without text are read when they appear
ERP_SINGLE = _on("RFQ_ERP_SINGLE", True)                        # one ERP mission for all catalogue groups

# robustness (on: no effect unless the situation occurs)
TAB_ISOLATION = _on("RFQ_TAB_ISOLATION", True)                  # own tab when two roles share one website
GAP_RECOVERY = _on("RFQ_GAP_RECOVERY", True)                    # look for missing facts on another website
CROSS_KINDS = _on("RFQ_CROSS_KINDS", True)                      # missions take along evidence of other roles they meet

# performance steps: off until paired test runs confirm them (docs/13 §4)
BRIEF_SPLIT = _on("RFQ_BRIEF_SPLIT", False)                     # core brief fields first, the rest in parallel
WAIT_ON_BACKGROUND = _on("RFQ_WAIT_ON_BACKGROUND", False)       # wait_for returns when a background result arrives
LLM_LANES = _on("RFQ_LLM_LANES", False)                         # separate model slots for navigation and extraction
EXTRACT_THEN = _on("RFQ_EXTRACT_THEN", False)                   # extract(..., then_click) / extract_urls(..., then_open)
LINKS_IN_RESULTS = _on("RFQ_LINKS_IN_RESULTS", False)           # extract_urls results list the links found there
COMPACT_HISTORY = _on("RFQ_COMPACT_HISTORY", False)             # older steps as one short line each
SCHEMA_TRIM = _on("RFQ_SCHEMA_TRIM", False)                     # extraction schemas without copied prose
